True def transform(grid):
    width = len(grid[0])
    center = next(c for c, value in enumerate(grid[0]) if value == 2)
    out = [[0] * width for _ in range(width)]
    for r in range(width):
        left = max(0, center - r)
        right = min(width - 1, center + r)
        for c in range(left, right + 1):
            if abs(c - center) == r:
                out[r][c] = 2
            elif (c - r - center) % 4 == 0:
                out[r][c] = 1
    return out
